#include "WorldAiGameplayBatch.h"
#include "json.hpp"
#include <stdexcept>
#include <unordered_set>
namespace Silver::WorldEditor
{
namespace{using Json=nlohmann::json;constexpr std::size_t MaxBytes=2*1024*1024,MaxCommands=256;
WorldRegion R(const Json&j){WorldRegion r;r.Id=j.value("id",NoRegion);r.Name=j.value("name","");r.Shape=j.value("shape","rectangle")=="circle"?WorldRegionShape::Circle:WorldRegionShape::Rectangle;r.X1=j.value("x1",0.f);r.Y1=j.value("y1",0.f);r.X2=j.value("x2",0.f);r.Y2=j.value("y2",0.f);r.Radius=j.value("radius",0.f);r.Tag=j.value("tag","");return r;}
WorldTrigger T(const Json&j){WorldTrigger t;t.Id=j.value("id",NoTrigger);t.Name=j.value("name","");t.Event=j.value("event","");t.Region=j.value("region",NoRegion);t.Conditions=j.value("conditions",std::vector<std::string>{});t.Actions=j.value("actions",std::vector<std::string>{});t.Enabled=j.value("enabled",true);return t;}}
WorldAiGameplayBatch WorldAiGameplayBatch::Decode(std::span<const std::uint8_t>b){if(b.empty()||b.size()>MaxBytes)throw std::invalid_argument("AI gameplay batch fuera de limites.");Json j;try{j=Json::parse(std::string(reinterpret_cast<const char*>(b.data()),b.size()));}catch(const Json::exception&){throw std::invalid_argument("AI gameplay batch JSON invalido.");}if(j.value("schema","")!=Schema)throw std::invalid_argument("AI gameplay schema incompatible.");WorldAiGameplayBatch x;x.RequestId=j.value("requestId","");x.MapId=j.value("mapId",-1);x.Safety=j.value("safety","");if(x.RequestId.empty()||x.MapId<0||x.Safety!="CANDIDATE_ONLY; NO_AUTO_APPLY")throw std::invalid_argument("AI gameplay batch inseguro/incompleto.");std::unordered_set<RegionId>ri;std::unordered_set<TriggerId>ti;for(const auto&v:j.value("regions",Json::array())){if(x.Regions.size()>=MaxCommands)throw std::length_error("Demasiados region commands.");WorldAiRegionCommand c;c.Id=v.value("id",NoRegion);c.Expected=R(v.at("expected"));c.Desired=R(v.at("desired"));if(c.Id==NoRegion||c.Expected.Id!=c.Id||c.Desired.Id!=c.Id||!ri.insert(c.Id).second)throw std::invalid_argument("Region command ID invalido.");x.Regions.push_back(std::move(c));}for(const auto&v:j.value("triggers",Json::array())){if(x.Triggers.size()>=MaxCommands)throw std::length_error("Demasiados trigger commands.");WorldAiTriggerCommand c;c.Id=v.value("id",NoTrigger);c.Expected=T(v.at("expected"));c.Desired=T(v.at("desired"));if(c.Id==NoTrigger||c.Expected.Id!=c.Id||c.Desired.Id!=c.Id||!ti.insert(c.Id).second)throw std::invalid_argument("Trigger command ID invalido.");x.Triggers.push_back(std::move(c));}return x;}
bool WorldAiGameplayBatch::Validate(const WorldRegionDocument&r,const WorldTriggerDocument&t,std::string&e)const{for(const auto&c:Regions){const auto*p=r.Find(c.Id);if(!p||!(*p==c.Expected)){e="AI Region Expected no coincide con estado actual.";return false;}}for(const auto&c:Triggers){const auto*p=t.Find(c.Id);if(!p||!(*p==c.Expected)){e="AI Trigger Expected no coincide con estado actual.";return false;}if(c.Desired.Region!=NoRegion&&!r.Find(c.Desired.Region)){e="AI Trigger referencia Region inexistente.";return false;}}e.clear();return true;}
bool WorldAiGameplayBatch::Apply(WorldRegionDocument&r,WorldTriggerDocument&t,std::string&e)const{if(!Validate(r,t,e))return false;bool changed=false;for(const auto&c:Regions)changed=r.Set(c.Id,c.Desired,"AI: Edit Region")||changed;for(const auto&c:Triggers)changed=t.Set(c.Id,c.Desired,"AI: Edit Trigger")||changed;if(!changed){e="AI gameplay batch no produjo cambios.";return false;}e.clear();return true;}
}
